item.content:encoded:
.container-fluid-with-max-width {
    max-width: 1500px;
    padding: 0 30px;
}
/* Remove WordPress's forced 2:1 placeholder for lazy-loaded images */
.post-card img.wp-post-image {
    contain-intrinsic-size: none;
}
/* Ensure images fill the card width and maintain their natural aspect ratio */
.post-card .entry-thumb-link img {
    width: 100%;
    height: auto;
    display: block;
}

